INSERT INTO `wp_posts` VALUES (20,1,'2026-04-06 09:49:15','2026-04-06 09:49:15','<!-- wp:heading {\"level\":1,\"className\":\"header-brush-1\"} -->\n<h1 class=\"wp-block-heading header-brush-1\">Home</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Soms kun je in het leven om allerlei redenen vastlopen. Dan is het fijn om iemand naast je te hebben die met je meedenkt en je ondersteunt op een manier die echt bij jou past. Geen therapie, maar persoonlijke begeleiding en praktische hulp waar nodig.<br>Dat is wat je vindt bij Unikko.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"header-flower-l\"} -->\n<h2 class=\"wp-block-heading header-flower-l\">Voor wie</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p>Volwassenen met een hulpvraag op het gebied van:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>eenzaamheid en sociale aansluiting</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>betekenisvol bezig zijn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>rouw en verlies</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>zelfredzaamheid en eigen regie</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p>Iedereen die (nog) geen specifieke hulpvraag heeft, maar wel behoefte aan een<br>gesprekspartner die:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>luistert zonder oordeel of invulling</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>ruimte geeft aan het unieke persoonlijke verhaal</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>een gelijkwaardige en betrokken sparringpartner is</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>kan helpen bij het vinden van praktische oplossingen en een nieuw perspectief</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:heading {\"className\":\"header-flower-l\"} -->\n<h2 class=\"wp-block-heading header-flower-l\">De waarde van meedoen</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Voor veel mensen is kwaliteit van leven sterk verbonden met meedoen. Het gaat dan over erbij horen, je verbonden voelen met anderen en betekenis ervaren. De een vindt het in een gedeelde hobby of interesse, vrijwilligerswerk of muziek maken, voor de ander is het samen wandelen, een fijn gesprek of een kopje koffie op een terras.<br>Als meedoen niet meer vanzelfsprekend is maar wel een wens, verkennen we samen welke vormen haalbaar zijn en passen bij iemands mogelijkheden en tempo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"align\":\"wide\",\"className\":\"header-flower-l\"} -->\n<h2 class=\"wp-block-heading alignwide header-flower-l\">Onderleggers</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>In onze werkwijze laten we ons o.a. inspireren door het gedachtegoed dat ten grondslag ligt aan Steunend Relationeel Handelen, Presentiegerichtheid en de inzichten van Jim van Os en Dirk de Wachter.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Home','','publish','closed','closed','','home','','','2026-05-25 12:22:42','2026-05-25 12:22:42','',0,'http://unikko.local/?page_id=20',0,'page','',0);
INSERT INTO `wp_posts` VALUES (21,1,'2026-04-06 09:49:15','2026-04-06 09:49:15','<!-- wp:paragraph -->\n<p>Soms kun je in het leven om allerlei redenen vastlopen. Dan is het fijn om iemand naast je te hebben die met je meedenkt en je ondersteunt op een manier die echt bij jou past. Geen therapie, maar persoonlijke begeleiding en praktische hulp waar nodig.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dat is wat je vindt bij Unikko.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Voor wie</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p>Volwassenen met een hulpvraag op het gebied van:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>eenzaamheid en sociale aansluiting</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>betekenisvol bezig zijn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>rouw en verlies</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>zelfredzaamheid en eigen regie</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p>Iedereen die (nog) geen specifieke hulpvraag heeft, maar wel behoefte aan een gesprekspartner die:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>luistert zonder oordeel of invulling</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>ruimte geeft aan het unieke persoonlijke verhaal</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>een gelijkwaardige en betrokken sparringspartner is</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>kan helpen bij het vinden van praktische oplossingen en een nieuw perspectief</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">De waarde van meedoen</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Voor veel mensen is kwaliteit van leven sterk verbonden met meedoen. Het gaat dan over erbij horen, je verbonden voelen met anderen en betekenis ervaren. De een vindt het in een gedeelde hobby of interesse, vrijwilligerswerk of muziek maken, voor de ander is het samen wandelen, een fijn gesprek of een kopje koffie op een terras.<br>Als meedoen niet meer vanzelfsprekend is maar wel een wens, verkennen we samen welke vormen haalbaar zijn en passen bij iemands mogelijkheden en tempo.</p>\n<!-- /wp:paragraph -->','Home','','inherit','closed','closed','','20-revision-v1','','','2026-04-06 09:49:15','2026-04-06 09:49:15','',20,'http://unikko.local/?p=21',0,'revision','',0);
